    <<0:1, X:7, Rest/binary>>, N, Acc, _, TrUserData
) ->
    Key = X bsl N + Acc,
    case Key band 7 of
        0 ->
            'skip_varint_temporal.api.workflowservice.v1.StartBatchOperationResponse'(
                Rest, 0, 0, Key bsr 3, TrUserData
            );
        1 ->
            'skip_64_temporal.api.workflowservice.v1.StartBatchOperationResponse'(
                Rest, 0, 0, Key bsr 3, TrUserData
            );
        2 ->
            'skip_length_delimited_temporal.api.workflowservice.v1.StartBatchOperationResponse'(
                Rest, 0, 0, Key bsr 3, TrUserData
            );
        3 ->
            'skip_group_temporal.api.workflowservice.v1.StartBatchOperationResponse'(
                Rest, 0, 0, Key bsr 3, TrUserData
            );
        5 ->
            'skip_32_temporal.api.workflowservice.v1.StartBatchOperationResponse'(
                Rest, 0, 0, Key bsr 3, TrUserData
            )
    end;
