'dg_read_field_def_temporal.api.common.v1.WorkerSelector'(
    <<1:1, X:7, Rest/binary>>, N, Acc, F, F@_1, TrUserData
) when N < 32 - 7 ->
    'dg_read_field_def_temporal.api.common.v1.WorkerSelector'(
        Rest, N + 7, X bsl N + Acc, F, F@_1, TrUserData
    );
'dg_read_field_def_temporal.api.common.v1.WorkerSelector'(
    <<0:1, X:7, Rest/binary>>, N, Acc, _, F@_1, TrUserData
) ->
    Key = X bsl N + Acc,
    case Key of
        10 ->
            'd_field_temporal.api.common.v1.WorkerSelector_worker_instance_key'(
                Rest, 0, 0, 0, F@_1, TrUserData
            );
        _ ->
            case Key band 7 of
                0 ->
                    'skip_varint_temporal.api.common.v1.WorkerSelector'(
                        Rest, 0, 0, Key bsr 3, F@_1, TrUserData
                    );
                1 ->
                    'skip_64_temporal.api.common.v1.WorkerSelector'(
                        Rest, 0, 0, Key bsr 3, F@_1, TrUserData
                    );
                2 ->
                    'skip_length_delimited_temporal.api.common.v1.WorkerSelector'(
                        Rest, 0, 0, Key bsr 3, F@_1, TrUserData
                    );
                3 ->
                    'skip_group_temporal.api.common.v1.WorkerSelector'(
                        Rest, 0, 0, Key bsr 3, F@_1, TrUserData
                    );
                5 ->
                    'skip_32_temporal.api.common.v1.WorkerSelector'(
                        Rest, 0, 0, Key bsr 3, F@_1, TrUserData
                    )
            end
    end;
