'dg_read_field_def_temporal.api.history.v1.History'(
    <<0:1, X:7, Rest/binary>>, N, Acc, _, F@_1, TrUserData
) ->
    Key = X bsl N + Acc,
    case Key of
        10 ->
            'd_field_temporal.api.history.v1.History_events'(Rest, 0, 0, 0, F@_1, TrUserData);
        _ ->
            case Key band 7 of
                0 ->
                    'skip_varint_temporal.api.history.v1.History'(
                        Rest, 0, 0, Key bsr 3, F@_1, TrUserData
                    );
                1 ->
                    'skip_64_temporal.api.history.v1.History'(
                        Rest, 0, 0, Key bsr 3, F@_1, TrUserData
                    );
                2 ->
                    'skip_length_delimited_temporal.api.history.v1.History'(
                        Rest, 0, 0, Key bsr 3, F@_1, TrUserData
                    );
                3 ->
                    'skip_group_temporal.api.history.v1.History'(
                        Rest, 0, 0, Key bsr 3, F@_1, TrUserData
                    );
                5 ->
                    'skip_32_temporal.api.history.v1.History'(
                        Rest, 0, 0, Key bsr 3, F@_1, TrUserData
                    )
            end
    end;
'dg_read_field_def_temporal.api.history.v1.History'(<<>>, 0, 0, _, R1, TrUserData) ->
    S1 = #{},
    if
        R1 == '$undef' -> S1;
        true -> S1#{events => lists_reverse(R1, TrUserData)}
    end.

