'dg_read_field_def_temporal.api.deployment.v1.WorkerDeploymentOptions'(
    <<1:1, X:7, Rest/binary>>, N, Acc, F, F@_1, F@_2, F@_3, TrUserData
) when N < 32 - 7 ->
    'dg_read_field_def_temporal.api.deployment.v1.WorkerDeploymentOptions'(
        Rest, N + 7, X bsl N + Acc, F, F@_1, F@_2, F@_3, TrUserData
    );
'dg_read_field_def_temporal.api.deployment.v1.WorkerDeploymentOptions'(
    <<0:1, X:7, Rest/binary>>, N, Acc, _, F@_1, F@_2, F@_3, TrUserData
) ->
    Key = X bsl N + Acc,
    case Key of
        10 ->
            'd_field_temporal.api.deployment.v1.WorkerDeploymentOptions_deployment_name'(
                Rest, 0, 0, 0, F@_1, F@_2, F@_3, TrUserData
            );
        18 ->
            'd_field_temporal.api.deployment.v1.WorkerDeploymentOptions_build_id'(
                Rest, 0, 0, 0, F@_1, F@_2, F@_3, TrUserData
            );
        24 ->
            'd_field_temporal.api.deployment.v1.WorkerDeploymentOptions_worker_versioning_mode'(
                Rest, 0, 0, 0, F@_1, F@_2, F@_3, TrUserData
            );
        _ ->
            case Key band 7 of
                0 ->
                    'skip_varint_temporal.api.deployment.v1.WorkerDeploymentOptions'(
                        Rest, 0, 0, Key bsr 3, F@_1, F@_2, F@_3, TrUserData
                    );
                1 ->
                    'skip_64_temporal.api.deployment.v1.WorkerDeploymentOptions'(
                        Rest, 0, 0, Key bsr 3, F@_1, F@_2, F@_3, TrUserData
                    );
                2 ->
                    'skip_length_delimited_temporal.api.deployment.v1.WorkerDeploymentOptions'(
                        Rest, 0, 0, Key bsr 3, F@_1, F@_2, F@_3, TrUserData
                    );
                3 ->
                    'skip_group_temporal.api.deployment.v1.WorkerDeploymentOptions'(
                        Rest, 0, 0, Key bsr 3, F@_1, F@_2, F@_3, TrUserData
                    );
                5 ->
                    'skip_32_temporal.api.deployment.v1.WorkerDeploymentOptions'(
                        Rest, 0, 0, Key bsr 3, F@_1, F@_2, F@_3, TrUserData
                    )
            end
    end;
'dg_read_field_def_temporal.api.deployment.v1.WorkerDeploymentOptions'(
    <<>>, 0, 0, _, F@_1, F@_2, F@_3, _
) ->
    #{deployment_name => F@_1, build_id => F@_2, worker_versioning_mode => F@_3}.

