'dg_read_field_def_temporal.api.failure.v1.NexusHandlerFailureInfo'(
    <<1:1, X:7, Rest/binary>>, N, Acc, F, F@_1, F@_2, TrUserData
) when N < 32 - 7 ->
    'dg_read_field_def_temporal.api.failure.v1.NexusHandlerFailureInfo'(
        Rest, N + 7, X bsl N + Acc, F, F@_1, F@_2, TrUserData
    );
'dg_read_field_def_temporal.api.failure.v1.NexusHandlerFailureInfo'(
    <<0:1, X:7, Rest/binary>>, N, Acc, _, F@_1, F@_2, TrUserData
) ->
    Key = X bsl N + Acc,
    case Key of
        10 ->
            'd_field_temporal.api.failure.v1.NexusHandlerFailureInfo_type'(
                Rest, 0, 0, 0, F@_1, F@_2, TrUserData
            );
        16 ->
            'd_field_temporal.api.failure.v1.NexusHandlerFailureInfo_retry_behavior'(
                Rest, 0, 0, 0, F@_1, F@_2, TrUserData
            );
        _ ->
            case Key band 7 of
                0 ->
                    'skip_varint_temporal.api.failure.v1.NexusHandlerFailureInfo'(
                        Rest, 0, 0, Key bsr 3, F@_1, F@_2, TrUserData
                    );
                1 ->
                    'skip_64_temporal.api.failure.v1.NexusHandlerFailureInfo'(
                        Rest, 0, 0, Key bsr 3, F@_1, F@_2, TrUserData
                    );
                2 ->
                    'skip_length_delimited_temporal.api.failure.v1.NexusHandlerFailureInfo'(
                        Rest, 0, 0, Key bsr 3, F@_1, F@_2, TrUserData
                    );
                3 ->
                    'skip_group_temporal.api.failure.v1.NexusHandlerFailureInfo'(
                        Rest, 0, 0, Key bsr 3, F@_1, F@_2, TrUserData
                    );
                5 ->
                    'skip_32_temporal.api.failure.v1.NexusHandlerFailureInfo'(
                        Rest, 0, 0, Key bsr 3, F@_1, F@_2, TrUserData
                    )
            end
    end;
'dg_read_field_def_temporal.api.failure.v1.NexusHandlerFailureInfo'(<<>>, 0, 0, _, F@_1, F@_2, _) ->
    #{type => F@_1, retry_behavior => F@_2}.

