'dg_read_field_def_temporal.api.update.v1.WaitPolicy'(
    <<1:1, X:7, Rest/binary>>, N, Acc, F, F@_1, TrUserData
) when N < 32 - 7 ->
    'dg_read_field_def_temporal.api.update.v1.WaitPolicy'(
