                    );
                5 ->
                    'skip_32_temporal.api.update.v1.WaitPolicy'(
                        Rest, 0, 0, Key bsr 3, F@_1, TrUserData
                    )
            end
    end;
'dg_read_field_def_temporal.api.update.v1.WaitPolicy'(<<>>, 0, 0, _, F@_1, _) ->
