'd_field_temporal.api.update.v1.UpdateRef_workflow_execution'(
    <<1:1, X:7, Rest/binary>>, N, Acc, F, F@_1, F@_2, TrUserData
) when N < 57 ->
    'd_field_temporal.api.update.v1.UpdateRef_workflow_execution'(
        Rest, N + 7, X bsl N + Acc, F, F@_1, F@_2, TrUserData
    );
'd_field_temporal.api.update.v1.UpdateRef_workflow_execution'(
    <<0:1, X:7, Rest/binary>>, N, Acc, F, Prev, F@_2, TrUserData
) ->
    {NewFValue, RestF} = begin
        Len = X bsl N + Acc,
        <<Bs:Len/binary, Rest2/binary>> = Rest,
        {
            id('decode_msg_temporal.api.common.v1.WorkflowExecution'(Bs, TrUserData), TrUserData),
            Rest2
        }
    end,
    'dfp_read_field_def_temporal.api.update.v1.UpdateRef'(
        RestF,
        0,
        0,
        F,
        if
            Prev == '$undef' ->
                NewFValue;
            true ->
                'merge_msg_temporal.api.common.v1.WorkflowExecution'(Prev, NewFValue, TrUserData)
        end,
        F@_2,
        TrUserData
    ).

