'd_field_temporal.api.update.v1.Outcome_success'(
    <<1:1, X:7, Rest/binary>>, N, Acc, F, F@_1, TrUserData
) when N < 57 ->
    'd_field_temporal.api.update.v1.Outcome_success'(
        Rest, N + 7, X bsl N + Acc, F, F@_1, TrUserData
    );
'd_field_temporal.api.update.v1.Outcome_success'(
    <<0:1, X:7, Rest/binary>>, N, Acc, F, Prev, TrUserData
) ->
    {NewFValue, RestF} = begin
        Len = X bsl N + Acc,
        <<Bs:Len/binary, Rest2/binary>> = Rest,
        {id('decode_msg_temporal.api.common.v1.Payloads'(Bs, TrUserData), TrUserData), Rest2}
    end,
    'dfp_read_field_def_temporal.api.update.v1.Outcome'(
        RestF,
        0,
        0,
        F,
        case Prev of
            '$undef' ->
                id({success, NewFValue}, TrUserData);
            {success, MVPrev} ->
                id(
                    {success,
                        'merge_msg_temporal.api.common.v1.Payloads'(MVPrev, NewFValue, TrUserData)},
                    TrUserData
                );
            _ ->
                id({success, NewFValue}, TrUserData)
        end,
        TrUserData
    ).

