    <<0:1, X:7, Rest/binary>>, N, Acc, F, Prev, F@_2, F@_3, F@_4, F@_5, TrUserData
) ->
    {NewFValue, RestF} = begin
        Len = X bsl N + Acc,
        <<Bs:Len/binary, Rest2/binary>> = Rest,
        {id('decode_msg_temporal.api.version.v1.ReleaseInfo'(Bs, TrUserData), TrUserData), Rest2}
    end,
    'dfp_read_field_def_temporal.api.version.v1.VersionInfo'(
        RestF,
        0,
        0,
        F,
        if
            Prev == '$undef' -> NewFValue;
            true -> 'merge_msg_temporal.api.version.v1.ReleaseInfo'(Prev, NewFValue, TrUserData)
        end,
        F@_2,
        F@_3,
        F@_4,
        F@_5,
        TrUserData
    ).

