'dg_read_field_def_temporal.api.worker.v1.WorkerSlotsInfo'(
    <<0:1, X:7, Rest/binary>>, N, Acc, _, F@_1, F@_2, F@_3, F@_4, F@_5, F@_6, F@_7, TrUserData
) ->
    Key = X bsl N + Acc,
    case Key of
        8 ->
            'd_field_temporal.api.worker.v1.WorkerSlotsInfo_current_available_slots'(
                Rest, 0, 0, 0, F@_1, F@_2, F@_3, F@_4, F@_5, F@_6, F@_7, TrUserData
            );
        16 ->
