            );
        26 ->
            'd_field_temporal.api.worker.v1.WorkerSlotsInfo_slot_supplier_kind'(
                Rest, 0, 0, 0, F@_1, F@_2, F@_3, F@_4, F@_5, F@_6, F@_7, TrUserData
            );
        32 ->
            'd_field_temporal.api.worker.v1.WorkerSlotsInfo_total_processed_tasks'(
                Rest, 0, 0, 0, F@_1, F@_2, F@_3, F@_4, F@_5, F@_6, F@_7, TrUserData
            );
        40 ->
            'd_field_temporal.api.worker.v1.WorkerSlotsInfo_total_failed_tasks'(
                Rest, 0, 0, 0, F@_1, F@_2, F@_3, F@_4, F@_5, F@_6, F@_7, TrUserData
            );
        48 ->
            'd_field_temporal.api.worker.v1.WorkerSlotsInfo_last_interval_processed_tasks'(
                Rest, 0, 0, 0, F@_1, F@_2, F@_3, F@_4, F@_5, F@_6, F@_7, TrUserData
            );
        56 ->
            'd_field_temporal.api.worker.v1.WorkerSlotsInfo_last_interval_failure_tasks'(
                Rest, 0, 0, 0, F@_1, F@_2, F@_3, F@_4, F@_5, F@_6, F@_7, TrUserData
            );
        _ ->
            case Key band 7 of
                0 ->
                    'skip_varint_temporal.api.worker.v1.WorkerSlotsInfo'(
                        Rest, 0, 0, Key bsr 3, F@_1, F@_2, F@_3, F@_4, F@_5, F@_6, F@_7, TrUserData
                    );
                1 ->
                    'skip_64_temporal.api.worker.v1.WorkerSlotsInfo'(
                        Rest, 0, 0, Key bsr 3, F@_1, F@_2, F@_3, F@_4, F@_5, F@_6, F@_7, TrUserData
                    );
                2 ->
                    'skip_length_delimited_temporal.api.worker.v1.WorkerSlotsInfo'(
                        Rest, 0, 0, Key bsr 3, F@_1, F@_2, F@_3, F@_4, F@_5, F@_6, F@_7, TrUserData
                    );
                3 ->
                    'skip_group_temporal.api.worker.v1.WorkerSlotsInfo'(
                        Rest, 0, 0, Key bsr 3, F@_1, F@_2, F@_3, F@_4, F@_5, F@_6, F@_7, TrUserData
                    );
                5 ->
                    'skip_32_temporal.api.worker.v1.WorkerSlotsInfo'(
                        Rest, 0, 0, Key bsr 3, F@_1, F@_2, F@_3, F@_4, F@_5, F@_6, F@_7, TrUserData
                    )
            end
    end;
