) ->
    'dg_read_field_def_temporal.api.worker.v1.WorkerHostInfo'(
        Other, Z1, Z2, F, F@_1, F@_2, F@_3, F@_4, F@_5, TrUserData
    ).

'dg_read_field_def_temporal.api.worker.v1.WorkerHostInfo'(
    <<1:1, X:7, Rest/binary>>, N, Acc, F, F@_1, F@_2, F@_3, F@_4, F@_5, TrUserData
) when N < 32 - 7 ->
    'dg_read_field_def_temporal.api.worker.v1.WorkerHostInfo'(
        Rest, N + 7, X bsl N + Acc, F, F@_1, F@_2, F@_3, F@_4, F@_5, TrUserData
    );
'dg_read_field_def_temporal.api.worker.v1.WorkerHostInfo'(
    <<0:1, X:7, Rest/binary>>, N, Acc, _, F@_1, F@_2, F@_3, F@_4, F@_5, TrUserData
) ->
    Key = X bsl N + Acc,
    case Key of
        10 ->
            'd_field_temporal.api.worker.v1.WorkerHostInfo_host_name'(
                Rest, 0, 0, 0, F@_1, F@_2, F@_3, F@_4, F@_5, TrUserData
            );
        42 ->
            'd_field_temporal.api.worker.v1.WorkerHostInfo_worker_grouping_key'(
                Rest, 0, 0, 0, F@_1, F@_2, F@_3, F@_4, F@_5, TrUserData
            );
        18 ->
            'd_field_temporal.api.worker.v1.WorkerHostInfo_process_id'(
                Rest, 0, 0, 0, F@_1, F@_2, F@_3, F@_4, F@_5, TrUserData
            );
        29 ->
            'd_field_temporal.api.worker.v1.WorkerHostInfo_current_host_cpu_usage'(
                Rest, 0, 0, 0, F@_1, F@_2, F@_3, F@_4, F@_5, TrUserData
            );
        37 ->
            'd_field_temporal.api.worker.v1.WorkerHostInfo_current_host_mem_usage'(
                Rest, 0, 0, 0, F@_1, F@_2, F@_3, F@_4, F@_5, TrUserData
            );
        _ ->
            case Key band 7 of
                0 ->
                    'skip_varint_temporal.api.worker.v1.WorkerHostInfo'(
                        Rest, 0, 0, Key bsr 3, F@_1, F@_2, F@_3, F@_4, F@_5, TrUserData
                    );
                1 ->
                    'skip_64_temporal.api.worker.v1.WorkerHostInfo'(
                        Rest, 0, 0, Key bsr 3, F@_1, F@_2, F@_3, F@_4, F@_5, TrUserData
                    );
                2 ->
                    'skip_length_delimited_temporal.api.worker.v1.WorkerHostInfo'(
                        Rest, 0, 0, Key bsr 3, F@_1, F@_2, F@_3, F@_4, F@_5, TrUserData
                    );
                3 ->
                    'skip_group_temporal.api.worker.v1.WorkerHostInfo'(
                        Rest, 0, 0, Key bsr 3, F@_1, F@_2, F@_3, F@_4, F@_5, TrUserData
                    );
                5 ->
                    'skip_32_temporal.api.worker.v1.WorkerHostInfo'(
                        Rest, 0, 0, Key bsr 3, F@_1, F@_2, F@_3, F@_4, F@_5, TrUserData
                    )
            end
    end;
'dg_read_field_def_temporal.api.worker.v1.WorkerHostInfo'(
    <<>>, 0, 0, _, F@_1, F@_2, F@_3, F@_4, F@_5, _
) ->
    #{
        host_name => F@_1,
        worker_grouping_key => F@_2,
        process_id => F@_3,
        current_host_cpu_usage => F@_4,
        current_host_mem_usage => F@_5
    }.

'd_field_temporal.api.worker.v1.WorkerHostInfo_host_name'(
    <<1:1, X:7, Rest/binary>>, N, Acc, F, F@_1, F@_2, F@_3, F@_4, F@_5, TrUserData
) when N < 57 ->
    'd_field_temporal.api.worker.v1.WorkerHostInfo_host_name'(
        Rest, N + 7, X bsl N + Acc, F, F@_1, F@_2, F@_3, F@_4, F@_5, TrUserData
    );
'd_field_temporal.api.worker.v1.WorkerHostInfo_host_name'(
    <<0:1, X:7, Rest/binary>>, N, Acc, F, _, F@_2, F@_3, F@_4, F@_5, TrUserData
) ->
    {NewFValue, RestF} = begin
        Len = X bsl N + Acc,
        <<Utf8:Len/binary, Rest2/binary>> = Rest,
        {id(unicode:characters_to_list(Utf8, unicode), TrUserData), Rest2}
    end,
    'dfp_read_field_def_temporal.api.worker.v1.WorkerHostInfo'(
        RestF, 0, 0, F, NewFValue, F@_2, F@_3, F@_4, F@_5, TrUserData
    ).

