'dfp_read_field_def_temporal.api.worker.v1.WorkerInfo'(
    <<10, Rest/binary>>, Z1, Z2, F, F@_1, TrUserData
) ->
    'd_field_temporal.api.worker.v1.WorkerInfo_worker_heartbeat'(Rest, Z1, Z2, F, F@_1, TrUserData);
'dfp_read_field_def_temporal.api.worker.v1.WorkerInfo'(<<>>, 0, 0, _, F@_1, _) ->
    S1 = #{},
    if
        F@_1 == '$undef' -> S1;
        true -> S1#{worker_heartbeat => F@_1}
    end;
'dfp_read_field_def_temporal.api.worker.v1.WorkerInfo'(Other, Z1, Z2, F, F@_1, TrUserData) ->
    'dg_read_field_def_temporal.api.worker.v1.WorkerInfo'(Other, Z1, Z2, F, F@_1, TrUserData).

'dg_read_field_def_temporal.api.worker.v1.WorkerInfo'(
    <<1:1, X:7, Rest/binary>>, N, Acc, F, F@_1, TrUserData
) when N < 32 - 7 ->
    'dg_read_field_def_temporal.api.worker.v1.WorkerInfo'(
        Rest, N + 7, X bsl N + Acc, F, F@_1, TrUserData
    );
'dg_read_field_def_temporal.api.worker.v1.WorkerInfo'(
    <<0:1, X:7, Rest/binary>>, N, Acc, _, F@_1, TrUserData
) ->
    Key = X bsl N + Acc,
    case Key of
        10 ->
            'd_field_temporal.api.worker.v1.WorkerInfo_worker_heartbeat'(
                Rest, 0, 0, 0, F@_1, TrUserData
            );
        _ ->
            case Key band 7 of
                0 ->
                    'skip_varint_temporal.api.worker.v1.WorkerInfo'(
                        Rest, 0, 0, Key bsr 3, F@_1, TrUserData
                    );
                1 ->
                    'skip_64_temporal.api.worker.v1.WorkerInfo'(
                        Rest, 0, 0, Key bsr 3, F@_1, TrUserData
                    );
                2 ->
                    'skip_length_delimited_temporal.api.worker.v1.WorkerInfo'(
                        Rest, 0, 0, Key bsr 3, F@_1, TrUserData
                    );
                3 ->
                    'skip_group_temporal.api.worker.v1.WorkerInfo'(
                        Rest, 0, 0, Key bsr 3, F@_1, TrUserData
                    );
                5 ->
                    'skip_32_temporal.api.worker.v1.WorkerInfo'(
                        Rest, 0, 0, Key bsr 3, F@_1, TrUserData
                    )
            end
    end;
'dg_read_field_def_temporal.api.worker.v1.WorkerInfo'(<<>>, 0, 0, _, F@_1, _) ->
    S1 = #{},
    if
        F@_1 == '$undef' -> S1;
        true -> S1#{worker_heartbeat => F@_1}
    end.

