'd_field_temporal.api.worker.v1.WorkerInfo_worker_heartbeat'(
    <<0:1, X:7, Rest/binary>>, N, Acc, F, Prev, TrUserData
) ->
    {NewFValue, RestF} = begin
        Len = X bsl N + Acc,
        <<Bs:Len/binary, Rest2/binary>> = Rest,
        {id('decode_msg_temporal.api.worker.v1.WorkerHeartbeat'(Bs, TrUserData), TrUserData), Rest2}
    end,
    'dfp_read_field_def_temporal.api.worker.v1.WorkerInfo'(
        RestF,
        0,
        0,
        F,
        if
            Prev == '$undef' -> NewFValue;
            true -> 'merge_msg_temporal.api.worker.v1.WorkerHeartbeat'(Prev, NewFValue, TrUserData)
        end,
        TrUserData
    ).

