'to_json_msg_google.protobuf.Duration'(Msg, TrUserData) ->
    [Seconds, Nanos] = tj_get_fields(Msg, [{seconds, 2, 0, id}, {nanos, 3, 0, id}], TrUserData),
    SecondsStr = integer_to_list(Seconds),
    NanosStr = tj_dot_nanos(Nanos),
