'to_json_msg_google.protobuf.FieldMask'(Msg, TrUserData) ->
    [Paths] = tj_get_fields(Msg, [{paths, 2, [], id}], TrUserData),
    tj_string(tj_comma_join_lower_camel_case(Paths)).

tj_comma_join_lower_camel_case(Paths) ->
    tj_strjoin(",", [tj_lower_camel_case_path(P) || P <- Paths]).

tj_lower_camel_case_path(S) ->
    tj_strjoin($., [tj_lower_camel_case(Comp) || Comp <- tj_strsplit($., S)]).

tj_strjoin(_Sep, []) -> "";
tj_strjoin(Sep, [Hd | Tl]) -> [Hd | [[Sep, Elem] || Elem <- Tl]].

tj_strsplit(Sep, Str) -> tj_strsplit_2(Sep, Str, "", []).

tj_strsplit_2(Sep, [Sep | Tl], Curr, Acc) ->
    tj_strsplit_2(Sep, Tl, "", [lists:reverse(Curr) | Acc]);
tj_strsplit_2(Sep, [C | Tl], Curr, Acc) ->
    tj_strsplit_2(Sep, Tl, [C | Curr], Acc);
tj_strsplit_2(_Sep, [], Curr, Acc) ->
    if
        Curr =:= "" -> lists:reverse(Acc);
        Curr =/= "" -> lists:reverse([lists:reverse(Curr) | Acc])
    end.

tj_lower_camel_case(S) ->
    [C1 | Rest] = tj_camel_case(S, true),
    [tj_lower_case_letter(C1) | Rest].

tj_camel_case([C | Tl], CapNextLetter) when $a =< C, C =< $z ->
    if
        CapNextLetter -> [tj_capitalize_letter(C) | tj_camel_case(Tl, false)];
        not CapNextLetter -> [C | tj_camel_case(Tl, false)]
    end;
tj_camel_case([C | Tl], _) when $A =< C, C =< $Z -> [C | tj_camel_case(Tl, false)];
tj_camel_case([D | Tl], _) when $0 =< D, D =< $9 -> [D | tj_camel_case(Tl, true)];
tj_camel_case([_ | Tl], _) ->
    tj_camel_case(Tl, true);
tj_camel_case([], _) ->
    [].

tj_capitalize_letter(C) -> C + ($A - $a).

tj_lower_case_letter(C) when $A =< C, C =< $Z -> C - ($A - $a);
tj_lower_case_letter(C) -> C.

'to_json_msg_google.protobuf.Timestamp'(Msg, TrUserData) ->
    [Seconds, Nanos] = tj_get_fields(Msg, [{seconds, 2, 0, id}, {nanos, 3, 0, id}], TrUserData),
    Gs1970 = 62167219200,
