    DateStr = io_lib:format("~4..0w-~2..0w-~2..0wT~2..0w:~2..0w:~2..0w", [YYYY, M, D, HH, MM, SS]),
    NanosStr = tj_dot_nanos(Nanos),
    tj_string([DateStr, NanosStr, "Z"]).

