'from_json_msg_google.protobuf.Duration'(Str, TrUserData) ->
    {Seconds, Nanos} = fj_parse_duration_s1(fj_ensure_list(Str)),
    fj_mk_msg(
        [Seconds, Nanos],
        'google.protobuf.Duration',
        [{seconds, 2, 0, id}, {nanos, 3, 0, id}],
        TrUserData
    ).

fj_parse_duration_s1("-" ++ Rest) -> fj_parse_duration_s2(Rest, neg, "");
fj_parse_duration_s1(Rest) -> fj_parse_duration_s2(Rest, pos, "").

fj_parse_duration_s2("." ++ Rest, Sign, Acc) ->
    Seconds = list_to_integer(lists:reverse(Acc)),
    fj_parse_duration_n(Rest, Sign, Seconds, "");
fj_parse_duration_s2("s", Sign, Acc) ->
    Seconds = list_to_integer(lists:reverse(Acc)),
    if
        Sign == pos -> {Seconds, 0};
        Sign == neg -> {-Seconds, 0}
    end;
fj_parse_duration_s2([D | Rest], Sign, Acc) when $0 =< D, D =< $9 ->
    fj_parse_duration_s2(Rest, Sign, [D | Acc]).

fj_parse_duration_n("s", Sign, Seconds, Acc) ->
    Acc1 =
        if
            Acc =:= "" -> "0";
            true -> Acc
        end,
    LFactor =
        case length(Acc1) of
            9 -> 1;
            8 -> 10;
            7 -> 100;
            6 -> 1000;
            5 -> 10000;
            4 -> 100000;
            3 -> 1000000;
            2 -> 10000000;
            1 -> 100000000;
            _ -> error({badnanos, lists:reverse(Acc)})
        end,
    Nanos = list_to_integer(lists:reverse(Acc1)),
    if
        Sign == pos -> {Seconds, Nanos * LFactor};
        Sign == neg -> {-Seconds, -Nanos * LFactor}
    end;
fj_parse_duration_n([D | Rest], Sign, Seconds, Acc) when $0 =< D, D =< $9 ->
    fj_parse_duration_n(Rest, Sign, Seconds, [D | Acc]).

'from_json_msg_google.protobuf.FieldMask'(JStr, TrUserData) ->
    fj_mk_msg(
