    ).

fj_field_names(JStr) ->
    Str = fj_ensure_list(JStr),
    Paths = fj_strsplit_nonempty($,, Str),
    [fj_string(fj_unlower_camel_case_path(Path)) || Path <- Paths].

fj_unlower_camel_case_path(S) ->
    fj_strjoin($., [fj_unlower_camel_case(Comp) || Comp <- fj_strsplit($., S)]).

fj_strjoin(_Sep, []) -> "";
fj_strjoin(Sep, [Hd | Tl]) -> [Hd | [[Sep, Elem] || Elem <- Tl]].

fj_strsplit(Sep, Str) -> fj_strsplit_2(Sep, Str, "", []).

fj_strsplit_2(Sep, [Sep | Tl], Curr, Acc) ->
    fj_strsplit_2(Sep, Tl, "", [lists:reverse(Curr) | Acc]);
fj_strsplit_2(Sep, [C | Tl], Curr, Acc) ->
    fj_strsplit_2(Sep, Tl, [C | Curr], Acc);
fj_strsplit_2(_Sep, [], Curr, Acc) ->
    if
        Curr =:= "" -> lists:reverse(Acc);
        Curr =/= "" -> lists:reverse([lists:reverse(Curr) | Acc])
    end.

fj_strsplit_nonempty(Sep, Str) -> fj_strsplit_nonempty_2(Sep, Str, none, []).

fj_strsplit_nonempty_2(Sep, [Sep | Tl], Curr, Acc) ->
    fj_strsplit_nonempty_2(Sep, Tl, none, fj_strsplit_add_to_acc(Curr, Acc));
fj_strsplit_nonempty_2(Sep, [C | Tl], Curr, Acc) ->
    fj_strsplit_nonempty_2(Sep, Tl, fj_strsplit_add_to_curr(C, Curr), Acc);
fj_strsplit_nonempty_2(_Sep, [], Curr, Acc) ->
    lists:reverse(fj_strsplit_add_to_acc(Curr, Acc)).

fj_strsplit_add_to_acc(none, Acc) -> Acc;
fj_strsplit_add_to_acc(Curr, Acc) -> [lists:reverse(Curr) | Acc].

fj_strsplit_add_to_curr(C, none) -> [C];
fj_strsplit_add_to_curr(C, Curr) -> [C | Curr].

fj_unlower_camel_case(S) -> fj_unlcc(S, i, "").

fj_unlcc([U | Tl], State, Acc) when $A =< U, U =< $Z ->
    if
        State =:= l, hd(Acc) =/= $_ -> fj_unlcc(Tl, u, [fj_lowercase(U), $_ | Acc]);
        true -> fj_unlcc(Tl, u, [fj_lowercase(U) | Acc])
    end;
fj_unlcc([NonU | Tl], State, Acc) ->
    if
        State =:= u, tl(Acc) =/= "", hd(tl(Acc)) =/= $_ ->
            [C | Acc1] = Acc,
            fj_unlcc(Tl, l, [NonU, C, $_ | Acc1]);
        true ->
            fj_unlcc(Tl, l, [NonU | Acc])
    end;
fj_unlcc("", _State, Acc) ->
    lists:reverse(Acc).

fj_lowercase(C) when $A =< C, C =< $Z -> C - ($A - $a);
fj_lowercase(C) -> C.

'from_json_msg_google.protobuf.Timestamp'(Str, TrUserData) ->
    {YYYY, M, D, HH, MM, SS, Nanos, Offset} = fj_parse_timestamp(fj_ensure_list(Str)),
    S1 = calendar:datetime_to_gregorian_seconds({{YYYY, M, D}, {HH, MM, SS}}),
    Gs1970 = 62167219200,
    Seconds = S1 - Gs1970 - Offset,
    fj_mk_msg(
        [Seconds, Nanos],
        'google.protobuf.Timestamp',
        [{seconds, 2, 0, id}, {nanos, 3, 0, id}],
        TrUserData
    ).

fj_parse_timestamp(S) -> fj_parse_timestamp_1(S).

fj_parse_timestamp_1(S) ->
    {YYYY, S1} = fj_read_int_until(S, $-),
    {M, S2} = fj_read_int_until(S1, $-),
    {D, S3} = fj_read_int_until(S2, $T),
    {HH, S4} = fj_read_int_until(S3, $:),
    {MM, S5} = fj_read_int_until(S4, $:),
    {SS, S6} = fj_read_int_until_any_of(S5, "Z.+-"),
    case S6 of
        "Z" ->
            {YYYY, M, D, HH, MM, SS, 0, 0};
        "." ++ S7 ->
            {Nanos, S8} = fj_read_nanos_until_any_of(S7, "Z+-"),
            case S8 of
                "Z" ->
                    {YYYY, M, D, HH, MM, SS, Nanos, 0};
                "+" ++ S9 ->
                    Offset = fj_read_timestamp_offs(S9),
                    {YYYY, M, D, HH, MM, SS, Nanos, Offset};
                "-" ++ S9 ->
                    Offset = fj_read_timestamp_offs(S9),
                    {YYYY, M, D, HH, MM, SS, Nanos, -Offset}
            end;
        "+" ++ S7 ->
            Offset = fj_read_timestamp_offs(S7),
            {YYYY, M, D, HH, MM, SS, 0, Offset};
        "-" ++ S7 ->
            Offset = fj_read_timestamp_offs(S7),
            {YYYY, M, D, HH, MM, SS, 0, -Offset}
    end.

fj_read_timestamp_offs(S) ->
    {OffsHH, OffsMMStr} = fj_read_int_until(S, $:),
    OffsMM = list_to_integer(OffsMMStr),
    OffsHH * 3600 + OffsMM.

fj_read_int_until(S, Delim) ->
    {S1, Rest} = fj_read_str_until(S, Delim, ""),
    {list_to_integer(S1), Rest}.

fj_read_int_until_any_of(S, Delims) ->
    {S1, Rest} = fj_read_str_until_any_of(S, Delims, ""),
    {list_to_integer(S1), Rest}.

fj_read_nanos_until_any_of(S, Delims) ->
    {NanosStr, Rest} = fj_read_str_until_any_of(S, Delims, ""),
    LFactor =
        case length(NanosStr) of
            9 -> 1;
            8 -> 10;
            7 -> 100;
            6 -> 1000;
            5 -> 10000;
            4 -> 100000;
            3 -> 1000000;
            2 -> 10000000;
            1 -> 100000000;
            _ -> error({badnanos, NanosStr})
        end,
    Nanos = list_to_integer(NanosStr) * LFactor,
    {Nanos, Rest}.

fj_read_str_until([Delim | Rest], Delim, Acc) -> {lists:reverse(Acc), Rest};
fj_read_str_until([C | Rest], Delim, Acc) -> fj_read_str_until(Rest, Delim, [C | Acc]).

fj_read_str_until_any_of([C | Rest] = S, Delims, Acc) ->
    case lists:member(C, Delims) of
        true -> {lists:reverse(Acc), S};
        false -> fj_read_str_until_any_of(Rest, Delims, [C | Acc])
    end.

