fj_iter(Map) -> maps:iterator(Map).

fj_next(Iter) -> maps:next(Iter).

-compile({nowarn_unused_function, fj_array/1}).
fj_array(L) -> L.

fj_mapfield_fold(MapMsgName, New, AddElem, Finalize, DecodeKey, DecodeValue, JMapfield, TrUserData) ->
    Finalize(
        fj_mapfield_fold_aux(
            fj_iter(JMapfield),
            MapMsgName,
            DecodeKey,
            DecodeValue,
            AddElem,
            New([], TrUserData),
            TrUserData
        ),
        TrUserData
    ).

fj_mapfield_fold_aux(JIter, MapMsgName, DecodeKey, DecodeValue, AddElem, Acc, TrUserData) ->
    case fj_next(JIter) of
        {JKey, JValue, JRest} ->
            EKey = DecodeKey(JKey),
            EValue = DecodeValue(JValue),
            TmpMsg = #{key => EKey, value => EValue},
            Acc1 = AddElem(TmpMsg, Acc, TrUserData),
            fj_mapfield_fold_aux(
                JRest, MapMsgName, DecodeKey, DecodeValue, AddElem, Acc1, TrUserData
            );
        none ->
            Acc
    end.

-compile({nowarn_unused_function, fj_int/1}).
fj_int(N) when is_integer(N) -> N;
fj_int(S) when is_binary(S) -> list_to_integer(binary_to_list(S));
fj_int(S) when is_list(S) -> list_to_integer(S).

-compile({nowarn_unused_function, fj_bool/1}).
fj_bool(B) when is_boolean(B) -> B;
fj_bool(B) when is_binary(B) ->
    case fj_bool_bin_casecanon(B, <<>>) of
        <<"true">> -> true;
        <<"false">> -> false;
        <<"1">> -> true;
        <<"0">> -> false
    end;
fj_bool(S) when is_list(S) -> fj_bool(list_to_binary(S)).

-compile({nowarn_unused_function, fj_bool_bin_casecanon/2}).
fj_bool_bin_casecanon(<<C, Rest/binary>>, Acc) when $A =< C, C =< $Z ->
    fj_bool_bin_casecanon(Rest, <<Acc/binary, (C + 32)>>);
fj_bool_bin_casecanon(<<C, Rest/binary>>, Acc) ->
    fj_bool_bin_casecanon(Rest, <<Acc/binary, C>>);
fj_bool_bin_casecanon(<<>>, Acc) ->
    Acc.

